        >
            <span
                aria-hidden="true"
                className="shrink-0 w-[15px] h-[15px] bg-current ch-mcp-icon"
                style={{
                    WebkitMaskImage: `url(${assetBase}/images/icons/icon-mcp.svg)`,
                    maskImage: `url(${assetBase}/images/icons/icon-mcp.svg)`,
